       val a3 = forall(ms, qs, nImplies, nUnit)
       if (debug)
         println("a1, a2, a3 = " + a1 + ", " + a2 + ", " + a3)
       a1 && a2 && a3
    }
    case (c1, Or(cs)) => cs.exists(imp(c1, _))
    case (Or(cs), c2) => cs.forall(imp(_, c2))
    }
    if (debug)
